def _network_status_rows():
    rows = []
    for label, value in NETWORK_STATUS:
        rows.append(
            '<div class="net-row"><span class="net-dot"></span>'
            '<span class="net-key">' + label + '</span>'
            '<span class="net-val">' + value + "</span></div>"
        )
    return "".join(rows)


